CREATE TABLE promotions (id BIGINT PRIMARY KEY, nom VARCHAR(120) NOT NULL);
CREATE TABLE etudiants (id BIGINT PRIMARY KEY, nom VARCHAR(120) NOT NULL, promotion_id BIGINT NOT NULL REFERENCES promotions(id));
CREATE TABLE sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titre VARCHAR(160) NOT NULL, promotion_id BIGINT NOT NULL REFERENCES promotions(id), code VARCHAR(12) NOT NULL UNIQUE, ouverture_at TIMESTAMP WITH TIME ZONE NOT NULL, expiration_at TIMESTAMP WITH TIME ZONE NOT NULL, cloture_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE presences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES sessions(id), etudiant_id BIGINT NOT NULL REFERENCES etudiants(id), source VARCHAR(20) NOT NULL, marquee_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(session_id, etudiant_id));
CREATE TABLE exercices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES sessions(id), etudiant_id BIGINT NOT NULL REFERENCES etudiants(id), lien VARCHAR(500) NOT NULL, statut VARCHAR(30) NOT NULL, depose_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(session_id, etudiant_id));
CREATE TABLE relectures (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, exercice_id BIGINT NOT NULL UNIQUE REFERENCES exercices(id), relecteur_id BIGINT NOT NULL REFERENCES etudiants(id), note INTEGER, commentaire VARCHAR(2000), rendue_at TIMESTAMP WITH TIME ZONE);
